import json, re
from pathlib import Path
p=Path(__file__).parent/'public'/'seed-reviews.js'
old=json.loads(p.read_text().removeprefix('const seedReviews = ').removesuffix(';\n'))
# (title, year, genre, official classification, cautious site age, verdict, plot/source-established topic,
#   spiritual reflection, positive theme, strength, second positive theme, strength, warning, severity, scripture, distinct discussion question, source)
L2025='https://www.commonsensemedia.org/lists/best-movies-of-the-year-2025'
L2026='https://www.commonsensemedia.org/lists/new-kids-movies'
rows=[
('David',2025,'Animation · Biblical','PG','10+','edifying','An animated musical retelling of David’s journey from shepherd to king, including battle scenes and the confrontation with Goliath.','Faith is presented as perseverance and humility rather than mere self-confidence. Compare cinematic additions with 1 Samuel, especially when discussing violence and kingship.','Faith and trust in God',5,'Courage and hope',5,'Battle violence and peril','Moderate','1 Samuel 17:45','Why does David trust God while facing Goliath?','https://www.commonsensemedia.org/movie-reviews/david'),
('Elio',2025,'Animation · Science Fiction','PG','7+','edifying','A lonely boy encounters an alien council and seeks a sense of belonging while facing science-fiction danger.','The longing for acceptance invites conversation about our worth and the duty to welcome isolated people. Science-fiction fantasy is not a literal account of the spiritual world.','Compassion and service',4,'Family and responsibility',3,'Alien peril and grief','Moderate','Romans 12:15','How do we notice and include someone who feels alone?','https://www.commonsensemedia.org/movie-reviews/elio'),
('Freakier Friday',2025,'Comedy · Family','PG','10+','neutral','Family members undergo comic body swaps as a blended family struggles with change, with mild language and jokes.','The improbable magical premise is a storytelling device; the teachable material concerns empathy, listening and respecting family members.','Family and responsibility',4,'Compassion and service',3,'Mild language and body-related jokes','Mild','Philippians 2:4','What changes when we try to see a situation from another person’s perspective?','https://www.bbfc.co.uk/release/freakier-friday-q29sbgvjdglvbjpwwc0xmdi4oda0'),
('In Your Dreams',2025,'Animation · Adventure','PG','10+','edifying','Siblings navigate an adventurous dream world and danger while learning lessons about their family and one another.','Dream imagery should not be confused with spiritual revelation. The central family relationship can support discussion of patience and loving another person despite conflict.','Family and responsibility',4,'Courage and hope',3,'Fantasy peril','Moderate','Colossians 3:13','How can siblings love each other through conflict?','https://www.commonsensemedia.org/movie-reviews/in-your-dreams'),
('Hola Frida',2025,'Animation · Biography','Unrated','10+','edifying','An animated coming-of-age story about a young artist confronting illness and discovering creativity.','The film can invite compassion toward those who suffer and gratitude for talents used with courage and generosity.','Courage and hope',4,'Compassion and service',3,'Illness and difficult emotions','Mild','2 Corinthians 1:3–4','How can we encourage a friend living with illness?','https://www.commonsensemedia.org/movie-reviews/hola-frida'),
('Arco',2025,'Animation · Adventure','PG','10+','edifying','A hopeful animated friendship adventure with moments of peril and mild scares.','Friendship and care for another person matter more than spectacle. Families can discuss helping someone without expecting anything in return.','Love and self-sacrifice',3,'Courage and hope',4,'Adventure peril and mild scary scenes','Mild','John 15:13','What does loyal friendship look like when someone is afraid?',L2025),
('Dora and the Search for Sol Dorado',2025,'Adventure · Family','Unrated','10+','neutral','A live-action search adventure involving friends, danger and positive messages.','This mainly recreational adventure provides an opportunity to examine courage, cooperation and the temptation to chase treasure at the expense of relationships.','Courage and hope',3,'Compassion and service',2,'Adventure peril','Moderate','Matthew 6:21','What is worth more than a treasure?',L2025),
('Guardians of the Galapagos',2025,'Documentary · Nature','Unrated','10+','edifying','A nature documentary about sea lions and conservation work, emphasizing collaboration.','Care for the natural world can be understood as stewardship of creation rather than worship of creation.','Compassion and service',4,'Truthfulness and integrity',2,'Wildlife and nature-related jeopardy','Unverified','Genesis 2:15','How can our family care for creation in practical ways?',L2025),
('Pangolin: Kulu’s Journey',2025,'Documentary · Animals','PG','10+','edifying','A nature documentary about a pangolin, featuring danger to animals and mild language.','Compassion extends to vulnerable creatures. Stewardship includes responsible action rather than merely feeling sympathy.','Compassion and service',5,'Courage and hope',3,'Animal peril and mild language','Mild','Proverbs 12:10','What responsibilities do people have toward threatened animals?',L2025),
('Pets',2025,'Documentary · Animals','Unrated','10+','neutral','A documentary exploring the relationships between people and animals, touching on difficult topics.','Gratitude for animals and compassionate care are valuable, but affection for animals should also coexist with responsibility to people.','Compassion and service',4,'Family and responsibility',2,'Emotionally difficult animal-related topics','Unverified','Proverbs 12:10','How can caring for an animal teach responsibility?',L2025),
('The Colors Within',2025,'Animation · Drama','PG','10+','edifying','An animated coming-of-age film about young musicians, friendship and self-expression.','Creative gifts can become acts of encouragement when practiced with humility and care for other people.','Compassion and service',3,'Courage and hope',4,'Coming-of-age emotional themes','Mild','1 Peter 4:10','How can musical talents be used in service to others?',L2025),
('A Tooth Fairy Tale',2025,'Animation · Fantasy','Unrated','7+','neutral','A whimsical fantasy adventure about a tooth fairy, involving some danger and potentially scary moments.','The supernatural elements are fairy-tale inventions, not Christian teaching about angels. Enjoy imaginative storytelling while distinguishing fantasy from faith.','Courage and hope',2,'Compassion and service',2,'Fantasy peril and possible scares','Mild','1 Thessalonians 5:21','How can we enjoy an imaginary story without believing its magic is real?',L2025),
('Grow',2025,'Family · Fantasy','PG','10+','neutral','A magical family story built around a giant pumpkin, with big emotions and some toilet humor.','The entertaining fantasy encourages conversation about managing strong feelings and treating others kindly.','Family and responsibility',3,'Courage and hope',2,'Rude humor and strong emotions','Mild','Ephesians 4:32','What can we do when our emotions become overwhelming?',L2025),
('Monster Mia',2026,'Animation · Fantasy','Unrated','7+','edifying','A human-and-monster adventure that challenges stereotypes and encourages empathy across differences.','Appearances can conceal goodness, and reflexive suspicion should give way to careful, compassionate judgment.','Compassion and service',4,'Truthfulness and integrity',3,'Monster-themed fantasy material','Unverified','1 Samuel 16:7','Why should we avoid judging someone by appearances?',L2026),
('PAW Patrol: The Dino Movie',2026,'Animation · Adventure','PG','7+','neutral','Rescue-pup heroes encounter dinosaurs and danger during a family adventure.','Cooperation and readiness to help can be positive lessons even in a lighthearted action story.','Compassion and service',3,'Courage and hope',3,'Dinosaur peril and action','Moderate','Galatians 6:2','When is courage really an act of service?','https://www.commonsensemedia.org/movie-reviews/paw-patrol-the-dino-movie'),
('The Cat in the Hat',2026,'Animation · Comedy','PG','7+','neutral','A colorful Seuss-inspired sibling adventure balancing whimsy, chaos and warm moments.','Enjoy the imaginative comedy while using the sibling relationships to discuss kindness and boundaries.','Family and responsibility',3,'Compassion and service',2,'Chaotic cartoon situations','Mild','Romans 12:10','How can fun be balanced with responsibility?','https://www.commonsensemedia.org/movie-reviews/the-cat-in-the-hat'),
('Tom and Jerry: Forbidden Compass',2026,'Animation · Comedy','PG','7+','neutral','The cat-and-mouse pair travel through a fantastical Chinese-themed adventure featuring action and mythical lore.','A fantasy setting can be enjoyed as fiction while discussing the importance of honesty and restraint in conflict.','Courage and hope',2,'Family and responsibility',2,'Comic action and fantasy lore','Mild','Proverbs 15:1','What might have prevented a comic argument from growing worse?',L2026),
('Coyote vs. Acme',2026,'Animation · Comedy','PG','10+','neutral','A live-action and animation hybrid brings Wile E. Coyote into a chaotic but emotional battle involving comic danger.','The comedy provides opportunities to discuss justice and mercy. Physical cartoon injury should not be mistaken for acceptable real-world conduct.','Truthfulness and integrity',3,'Courage and hope',3,'Cartoon violence and comic weapons','Moderate','Micah 6:8','Why does justice matter even in a silly comedy?','https://www.commonsensemedia.org/movie-reviews/coyote-vs-acme'),
('Minions & Monsters',2026,'Animation · Comedy','PG','10+','neutral','The Minions encounter outsized monsters and large-scale cartoon action in an entertainment-focused adventure.','Enjoyment and laughter can be wholesome, yet the story has limited explicit spiritual substance and cartoon violence should be kept in perspective.','Courage and hope',2,'Compassion and service',1,'Monster threats and cartoon violence','Moderate','Proverbs 17:22','Can we enjoy a movie without adopting every behavior in it?',L2026),
('Forgotten Island',2026,'Animation · Fantasy','PG','10+','neutral','An animated friendship adventure draws on Filipino mythology and includes frightening monsters.','Friendship may be commendable even when the fantasy draws on religious stories outside Christian faith. Make room for respectful conversation about myth versus revelation.','Love and self-sacrifice',3,'Courage and hope',3,'Monster scares and mythology-based imagery','Moderate','1 Thessalonians 5:21','How is a cultural myth different from Christian teaching?','https://www.commonsensemedia.org/movie-reviews/forgotten-island'),
('The Magic Faraway Tree',2026,'Fantasy · Family','PG','10+','neutral','A fanciful family adventure adapts a magical tree story and includes rude humor.','An imaginary world is not a claim about spiritual truth. Families can reflect on how imagination can coexist with responsibility and sound judgment.','Family and responsibility',3,'Courage and hope',3,'Rude humor and fantasy peril','Mild','Philippians 4:8','What parts of a fantasy story are worth imitating?',L2026),
('Not My Dog',2026,'Family · Drama','Unrated','10+','edifying','A family-friendly pet story includes bullying and mild language, with a relationship to a dog at its center.','Kindness to an animal should connect to gentleness toward vulnerable people, especially those targeted by bullying.','Compassion and service',4,'Courage and hope',3,'Bullying and mild language','Mild','Ephesians 4:32','How can we help someone being bullied?',L2026),
('Super-Charlie',2026,'Animation · Superhero','Unrated','10+','edifying','A child adjusts to the arrival of a younger sibling in an animated superhero adventure.','Sibling jealousy is a normal temptation that can be answered through gratitude and practical love rather than rivalry.','Family and responsibility',4,'Love and self-sacrifice',3,'Superhero adventure action','Unverified','Romans 12:10','How can an older sibling welcome a new baby?',L2026),
('Chickenhare and the Secret of the Groundhog',2026,'Animation · Adventure','Unrated','10+','neutral','An animated sequel combines mild peril with messages about self-discovery and friendship.','The movie can prompt conversations about identity being shaped through character and loving action rather than applause or appearance.','Courage and hope',3,'Compassion and service',3,'Mild adventure peril','Mild','1 Peter 4:10','How do we recognize our gifts without becoming proud?',L2026),
('Before the Ice Melts',2026,'Sports · Drama','Unrated','10+','edifying','A family-focused hockey drama about pursuing dreams and working through challenges.','Perseverance is valuable when joined with humility, gratitude and respect for teammates.','Courage and hope',4,'Truthfulness and integrity',3,'Competitive sports tension','Unverified','Colossians 3:23','How can ambition be pursued without becoming selfish?',L2026),
]
assert len(rows)==25, len(rows)
from urllib.parse import quote
existing={(r['title'].casefold(),r['year']) for r in old}
new=[]
for i,(title,year,genre,mpaa,age,verdict,synopsis,reflection,t1,v1,t2,v2,warning,severity,scripture,question,link) in enumerate(rows):
  assert (title.casefold(),year) not in existing,(title,year)
  # Source labels reflect a short external list description unless a full individual guide was inspected.
  detailed='/movie-reviews/' in link or 'bbfc.co.uk/release/' in link
  evid=f"The linked {'individual guide' if detailed else 'editorial movie list'} describes the movie's general story or major concerns; check the complete movie for any finer-grained claim."
  themes=[dict(name=t1,type='positive',score=v1,portrayal='affirmed',evidence=evid),dict(name=t2,type='positive',score=v2,portrayal='affirmed',evidence=evid)]
  # Never assert harmful theme scores based on a one-sentence summary.
  themes.append(dict(name='Violence and cruelty',type='harmful',score=None,portrayal='unverified',evidence='A complete violence breakdown was not verified for this batch.'))
  themes.append(dict(name='Sexual content and immodesty',type='harmful',score=None,portrayal='unverified',evidence='A complete sexual-content breakdown was not verified for this batch.'))
  themes.append(dict(name='Profanity and blasphemy',type='harmful',score=None,portrayal='unverified',evidence='A complete language breakdown was not verified for this batch.'))
  v={
    'id':re.sub('[^a-z0-9]+','-',f'film-{title.lower()}-{year}').strip('-'),
    'title':title,'year':year,'genre':genre,'officialRating':mpaa,'runtime':'',
    'synopsis':synopsis,
    'verdict':verdict,
    'verdictRationale':f'Provisional Coptic Orthodox interpretation: {reflection} This classification is based on the documented premise and major themes, not a full scene-by-scene verification; further content research could change it.',
    'age':age,'ageRationale':f'Conservative provisional site suggestion based on the cited public description, including {warning.lower()}. Complete content verification may require a different age recommendation.',
    'themes':themes,
    'warnings':[{'name':warning,'severity':severity,'details':('Not exhaustively verified. The linked public guide mentions this general area or theme; exact frequency and severity should be checked before editorial approval.' if severity!='Unverified' else 'Potentially relevant based on the premise; detailed severity not verified.')}],
    'reflection':reflection,'scripture':[scripture],
    'questions':[question,'Which of the film’s choices would you imitate, and which would you avoid?'],
    'sources':[{'label':'Common Sense Media — '+('individual movie guide' if detailed else '2025 / 2026 film list') if 'commonsensemedia.org' in link else 'BBFC — official content advice','url':link,'notes':'External editorial guidance informs the summary; spiritual verdicts and theme ratings are our own provisional interpretation. Full content audit pending.'}],
    'isSeed':True,'isDemo':False,'status':'provisional','featured':i<8,'reviewDepth':'preliminary',
    'posterClass':'p'+str(i%6+1)
  }
  new.append(v)
old+=new
p.write_text('const seedReviews = '+json.dumps(old,ensure_ascii=False,indent=2)+';\n')
(Path(__file__).parent/'public'/'batch2-review-data.json').write_text(json.dumps(new,ensure_ascii=False,indent=2))
print('New',len(new),'total',len(old))
